import React, { useEffect, useState, useContext } from "react";
import axios from "axios";
import { TrainingContext } from "./TrainingContext";
import { useNavigate, useLocation } from "react-router-dom";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const TrainingModelStep5 = () => {
  const { trainingDetails, setTrainingDetails } = useContext(TrainingContext);
  const navigate = useNavigate();

  const goToDashboard = () => {
    setTrainingDetails(null);
    navigate("/WebApplication/dashboard/")
  };

  const goToAllTrainings = () => {
    setTrainingDetails(null);
    navigate("/WebApplication/dashboard/allTrainingModel")
  };

  return (
    <div className="container-fluid py-1">
      <div className="row g-1">
        {/* LEFT PANEL – QUESTION BUILDER */}
        <div className="container vh-100 d-flex align-items-center justify-content-center">
          <div className="row w-100 justify-content-center">
            <div className="col-md-7 col-lg-5">
              <div className="card shadow-lg border-0 rounded-4 text-center">
                <div className="card-body p-5">
                  {/* Icon */}
                  <div className="mb-4">
                    <i className="bi bi-trophy-fill text-warning display-3"></i>
                  </div>

                  {/* Title */}
                  <h2 className="fw-bold mb-2">{trainingDetails.trainingName}</h2>

                  {/* Subtitle */}
                  <p className="text-muted mb-3">Created Successfully</p>

                  {/* User Name */}
                  <h5 className="fw-semibold text-primary mb-3">
                    Well done! 🎉
                  </h5>

                  {/* Message */}
                  <p className="text-secondary mb-4">
                    Keep up the great work. You are one step closer to mastering your
                    skills.
                  </p>

                  {/* Buttons */}
                  <div className="d-grid gap-2 d-sm-flex justify-content-sm-center">
                    <button
                      className="btn btn-primary px-4"
                      onClick={goToDashboard}
                    >
                      Go to Dashboard
                    </button>

                    <button
                      className="btn btn-outline-secondary px-4"
                      onClick={goToAllTrainings}
                    >
                      View Trainings
                    </button>
                  </div>
                </div>
              </div>

              {/* Footer */}
              <p className="text-center text-muted mt-4 small">
                © {new Date().getFullYear()} TrainOps • All Rights Reserved
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TrainingModelStep5;